#include <iostream>
#include <iomanip>
#include <cstdint>
#include <bitset>

void displayBits(std::uint32_t value) {
    std::cout << std::setw(10) << value << " = ";
    std::bitset<32> b(value);
    for (int i = 31; i >= 0; --i) {
        std::cout << b[i];
        if (i % 8 == 0 && i != 0) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    // Bitwise AND (&)
    std::uint32_t number1 = 65535;
    std::uint32_t mask = 1;
    std::cout << "Bitwise AND (&):\n";
    displayBits(number1);
    displayBits(mask);
    displayBits(number1 & mask);

    // Bitwise OR (|)
    number1 = 15;
    std::uint32_t setBits = 241;
    std::cout << "\nBitwise inclusive OR (|):\n";
    displayBits(number1);
    displayBits(setBits);
    displayBits(number1 | setBits);

    // Bitwise XOR (^)
    number1 = 139;
    std::uint32_t number2 = 199;
    std::cout << "\nBitwise exclusive OR (^):\n";
    displayBits(number1);
    displayBits(number2);
    displayBits(number1 ^ number2);

    // Bitwise complement (~)
    number1 = 21845;
    std::cout << "\nBitwise complement (~):\n";
    displayBits(number1);
    displayBits(~number1);

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdint>
#include <bitset>

void displayBits(std::uint32_t value) {
    std::cout << std::setw(7) << value << " = ";
    std::bitset<32> b(value);
    for (int i = 31; i >= 0; --i) {
        std::cout << b[i];
        if (i % 8 == 0 && i != 0) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    std::uint32_t number1 = 960;

    std::cout << "Original value:\n";
    displayBits(number1);

    std::cout << "\nLeft shifted 8 bit positions (number1 << 8):\n";
    displayBits(number1 << 8);

    std::cout << "\nRight shifted 8 bit positions (number1 >> 8):\n";
    displayBits(number1 >> 8);

    return 0;
}
